css:
.engage,
.engage *,
.engage *::before,
.engage *::after {
  box-sizing: border-box;
}

.engage {
  position: relative;
  width: 44em;
  height: 32em;
  font-size: 8px;
  display: grid;
  place-items: center;
  font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  user-select: none;
}

.eng-fire {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.scene {
  perspective: 110em;
}

.hw {
  position: relative;
  width: 36em;
  height: 23em;
  border: 0;
  padding: 0;
  background: none;
  cursor: pointer;
  display: block;
  transform: rotateX(28deg) rotateZ(-7deg);
  transform-style: preserve-3d;
  transition: transform 0.5s cubic-bezier(0.22, 1.6, 0.36, 1);
  will-change: transform;
}

.eng-fire:focus-visible ~ .scene .hw {
  outline: 0.3em solid #59ff9d;
  outline-offset: 0.6em;
  border-radius: 3em;
}

.base {
  position: absolute;
  inset: 0;
  border-radius: 2.6em;
  background: linear-gradient(180deg, #2b323a, #151a20 45%, #0a0e12);
  box-shadow:
    inset 0 0.1em 0 rgba(255, 255, 255, 0.08),
    0 0.4em 0 #0b0f13,
    0 0.7em 0 #180702,
    0 0.9em 0 #3d190a,
    0 1.1em 0 #8a4218,
    0 1.2em 0 #d1783a,
    0 1.3em 0 #ffdcb8,
    0 1.5em 0 #c1692c,
    0 1.7em 0 #6e3416,
    0 1.8em 0 #180702,
    0 2em 0 #0b0f13,
    0 2.4em 0 #06090c,
    0 3em 5em rgba(0, 0, 0, 0.72);
  transition: box-shadow 0.45s cubic-bezier(0.22, 1.4, 0.36, 1);
}

.trim {
  position: absolute;
  top: 14%;
  bottom: 14%;
  width: 0.7em;
  border-radius: 99em;
  background: linear-gradient(
      180deg,
      rgba(0, 0, 0, 0.85),
      rgba(0, 0, 0, 0) 16%,
      rgba(0, 0, 0, 0) 84%,
      rgba(0, 0, 0, 0.85)
    ),
    linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.45),
      rgba(255, 255, 255, 0) 30%
    ),
    linear-gradient(
      90deg,
      #180702,
      #3d190a 12%,
      #8a4218 26%,
      #d1783a 40%,
      #ffdcb8 50%,
      #f4b47a 58%,
      #c1692c 70%,
      #6e3416 85%,
      #180702
    );
  box-shadow:
    0 0 0.6em rgba(0, 0, 0, 0.8),
    0.1em 0.2em 0.4em rgba(0, 0, 0, 0.6);
}
.trim-l {
  left: -0.5em;
}
.trim-r {
  right: -0.5em;
}

.ring {
  position: absolute;
  inset: 0.7em;
  border-radius: 2.4em;
  pointer-events: none;
  transform: translateY(0) scale(1);
  border: 0.8em solid rgba(120, 200, 255, 0.08);
  transition: transform 0.5s cubic-bezier(0.22, 1.6, 0.36, 1);
}

.ring-glow {
  position: absolute;
  inset: -0.8em;
  border-radius: 2.4em;
  border: 0.6em solid rgba(64, 169, 255, 0.85);
  box-shadow:
    0 0 0.8em 0.2em rgba(140, 210, 255, 0.9),
    0 0 2em 0.8em rgba(47, 155, 255, 0.7),
    0 0 4.5em 1.8em rgba(34, 141, 255, 0.5),
    0 0 8em 3.2em rgba(34, 141, 255, 0.3),
    inset 0 0 1.6em rgba(140, 210, 255, 0.85),
    inset 0 0 0.6em rgba(255, 255, 255, 1);
  opacity: 0;
  will-change: opacity;
}

.ring-svg {
  position: absolute;
  inset: -0.8em;
  width: calc(100% + 1.6em);
  height: calc(100% + 1.6em);
  display: block;
}

.rv {
  stroke-dasharray: 100 200;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 0.45s cubic-bezier(0.4, 0, 0.2, 1);
}
.rv-halo3 {
  stroke: rgba(47, 155, 255, 0.12);
  stroke-width: 40;
}
.rv-halo2 {
  stroke: rgba(47, 155, 255, 0.3);
  stroke-width: 26;
}
.rv-halo1 {
  stroke: rgba(47, 155, 255, 0.55);
  stroke-width: 15;
}
.rv-tube {
  stroke: url(#ngn-t);
  stroke-width: 10;
}
.rv-ridge {
  stroke: #ffffff;
  stroke-width: 3.5;
}

.eng-fire:checked ~ .scene .rv {
  animation:
    rvA 3s linear,
    rvFlick 3s linear;
}
.eng-fire:user-valid:not(:checked) ~ .scene .rv {
  animation:
    rvB 3s linear,
    rvFlick 3s linear;
}
.eng-fire:checked ~ .scene .ring-glow {
  animation: glowA 3s linear;
}
.eng-fire:user-valid:not(:checked) ~ .scene .ring-glow {
  animation: glowB 3s linear;
}

@keyframes rvA {
  0% {
    stroke-dashoffset: 100;
  }
  22%,
  86% {
    stroke-dashoffset: 0;
  }
  100% {
    stroke-dashoffset: 100;
  }
}
@keyframes rvB {
  0% {
    stroke-dashoffset: 100;
  }
  22%,
  86% {
    stroke-dashoffset: 0;
  }
  100% {
    stroke-dashoffset: 100;
  }
}

@keyframes rvFlick {
  0%,
  22% {
    opacity: 1;
  }
  25% {
    opacity: 0.35;
  }
  27% {
    opacity: 1;
  }
  34% {
    opacity: 0.55;
  }
  36% {
    opacity: 1;
  }
  42% {
    opacity: 0.4;
  }
  44% {
    opacity: 0.9;
  }
  46% {
    opacity: 0.5;
  }
  48%,
  100% {
    opacity: 1;
  }
}

@keyframes glowA {
  0% {
    opacity: 0;
  }
  12% {
    opacity: 0.25;
  }
  22% {
    opacity: 0.9;
  }
  25% {
    opacity: 0.35;
  }
  27% {
    opacity: 1;
  }
  34% {
    opacity: 0.55;
  }
  36% {
    opacity: 1;
  }
  42% {
    opacity: 0.4;
  }
  44% {
    opacity: 0.9;
  }
  46% {
    opacity: 0.5;
  }
  48%,
  86% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}
@keyframes glowB {
  0% {
    opacity: 0;
  }
  12% {
    opacity: 0.25;
  }
  22% {
    opacity: 0.9;
  }
  25% {
    opacity: 0.35;
  }
  27% {
    opacity: 1;
  }
  34% {
    opacity: 0.55;
  }
  36% {
    opacity: 1;
  }
  42% {
    opacity: 0.4;
  }
  44% {
    opacity: 0.9;
  }
  46% {
    opacity: 0.5;
  }
  48%,
  86% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}

.plate {
  position: absolute;
  inset: 1.4em;
  border-radius: 1.8em;
  transform: translateY(0) scale(1);
  background: radial-gradient(
      130% 90% at 28% 16%,
      rgba(255, 255, 255, 0.5),
      rgba(255, 255, 255, 0) 55%
    ),
    radial-gradient(
      70% 45% at 50% 100%,
      rgba(53, 240, 150, 0.2),
      rgba(53, 240, 150, 0) 70%
    ),
    repeating-linear-gradient(
      0deg,
      rgba(255, 255, 255, 0.05) 0 0.1em,
      rgba(15, 25, 20, 0.06) 0.1em 0.3em
    ),
    linear-gradient(
      155deg,
      #dfe7e2,
      #b9c6bf 28%,
      #93a49c 52%,
      #6d7f77 75%,
      #55665e
    );
  box-shadow:
    inset 0 0.2em 0.2em rgba(255, 255, 255, 0.7),
    inset 0 -0.3em 0.7em rgba(10, 25, 20, 0.55),
    inset 0.3em 0 0.6em rgba(255, 255, 255, 0.22),
    inset -0.3em 0 0.7em rgba(10, 25, 20, 0.3),
    0 0 0 0.2em rgba(8, 18, 14, 0.92),
    0 1em 2.4em rgba(0, 0, 0, 0.5);
  transition:
    transform 0.5s cubic-bezier(0.22, 1.6, 0.36, 1),
    box-shadow 0.4s ease;
}

.plate::before {
  content: "";
  position: absolute;
  inset: 1.1em;
  border-radius: 1.2em;
  border: 0.1em solid rgba(12, 26, 20, 0.45);
  box-shadow: 0 0.1em 0 rgba(255, 255, 255, 0.28);
}

.screw {
  position: absolute;
  width: 1.8em;
  height: 1.8em;
  border-radius: 50%;
  background-image: radial-gradient(
      circle at 34% 28%,
      rgba(255, 255, 255, 0.95),
      rgba(255, 255, 255, 0) 24%
    ),
    repeating-radial-gradient(
      circle at 50% 50%,
      rgba(255, 255, 255, 0.16) 0 0.05em,
      rgba(0, 0, 0, 0.16) 0.05em 0.1em
    ),
    radial-gradient(
      circle at 35% 30%,
      #ffd9b8,
      #e07830 35%,
      #8a4218 62%,
      #4a2718 85%,
      #2a0f06
    );
  box-shadow:
    0 0 0 0.1em #0d0500,
    inset 0 -0.2em 0.3em rgba(0, 0, 0, 0.7),
    inset 0 0.1em 0.1em rgba(255, 230, 205, 0.9),
    0 0.1em 0.2em rgba(0, 0, 0, 0.5);
}

.screw::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 1em;
  height: 0.22em;
  border-radius: 0.1em;
  background: linear-gradient(90deg, #0d0500, #241008 50%, #0d0500);
  transform: translate(-50%, -50%) rotate(45deg);
  box-shadow:
    0 0.1em 0 rgba(255, 220, 190, 0.4),
    0 -0.05em 0 rgba(0, 0, 0, 0.6);
}

.tl {
  top: 0.9em;
  left: 1.1em;
}
.tr {
  top: 0.9em;
  right: 1.1em;
}
.bl {
  bottom: 0.9em;
  left: 1.1em;
}
.br {
  bottom: 0.9em;
  right: 1.1em;
}

.slot {
  position: absolute;
  top: 50%;
  width: 1.2em;
  height: 7.4em;
  transform: translateY(-50%);
  border-radius: 0.7em;
  background: linear-gradient(90deg, #0b1512, #04080a 50%, #0b1512);
  box-shadow:
    inset 0 0.3em 0.6em #000,
    inset 0 -0.2em 0.4em #000,
    0 0.1em 0 rgba(255, 255, 255, 0.22),
    0 0 0.8em 0.1em rgba(53, 240, 150, 0.28);
  transition: box-shadow 0.4s ease;
}
.slot-l {
  left: 4em;
}
.slot-r {
  right: 4em;
}

.clamp {
  position: absolute;
  top: 50%;
  width: 6.2em;
  height: 6em;
  transform: translateY(-50%);
  background: linear-gradient(
    180deg,
    rgba(0, 0, 0, 0) 40%,
    rgba(8, 4, 2, 0.9) 47% 53%,
    rgba(0, 0, 0, 0) 60%
  );
}
.clamp-l {
  left: -1.4em;
}
.clamp-r {
  right: -1.4em;
}

.tube {
  position: absolute;
  left: 0;
  right: 0;
  height: 2.5em;
  border-radius: 99em;
  transform: translateY(0);
  background: linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.55) 0%,
      rgba(255, 255, 255, 0) 22%
    ),
    linear-gradient(
      90deg,
      rgba(0, 0, 0, 0.6) 0%,
      rgba(0, 0, 0, 0.2) 8%,
      rgba(0, 0, 0, 0) 20%,
      rgba(0, 0, 0, 0) 78%,
      rgba(0, 0, 0, 0.3) 90%,
      rgba(0, 0, 0, 0.55) 100%
    ),
    linear-gradient(
      165deg,
      #180702 0%,
      #3d190a 10%,
      #8a4218 24%,
      #d1783a 38%,
      #ffdcb8 48%,
      #f4b47a 56%,
      #c1692c 68%,
      #6e3416 82%,
      #180702 100%
    );
  background-blend-mode: normal, multiply, normal;
  box-shadow:
    inset 0 0.15em 0.15em rgba(255, 240, 225, 0.55),
    inset 0 -0.4em 0.5em rgba(0, 0, 0, 0.65),
    inset 0.6em 0 0.6em rgba(0, 0, 0, 0.35),
    inset -0.6em 0 0.6em rgba(0, 0, 0, 0.35),
    0 0.4em 0.7em rgba(0, 0, 0, 0.55),
    0 0.9em 1.2em rgba(0, 0, 0, 0.35);
  transition: transform 0.6s cubic-bezier(0.3, 1.56, 0.4, 1) 0.04s;
}
.t1 {
  top: 0.2em;
}
.t2 {
  bottom: 0.2em;
}

.tube::after {
  content: "";
  position: absolute;
  left: 8%;
  right: 8%;
  top: 18%;
  height: 0.22em;
  border-radius: 0.2em;
  opacity: 0.95;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 246, 232, 0.95) 30%,
    rgba(255, 246, 232, 0.95) 62%,
    transparent
  );
  transition: opacity 0.3s ease;
}

.clamp::before {
  content: "";
  position: absolute;
  top: 0.3em;
  bottom: 0.3em;
  width: 1.5em;
  border-radius: 99em;
  background: linear-gradient(
    90deg,
    #180702,
    #3d190a 15%,
    #8a4218 30%,
    #d1783a 42%,
    #ffdcb8 52%,
    #f4b47a 60%,
    #c1692c 72%,
    #6e3416 86%,
    #180702
  );
  box-shadow:
    inset 0 0.15em 0.15em rgba(255, 240, 225, 0.55),
    inset 0 -0.4em 0.5em rgba(0, 0, 0, 0.7),
    -0.3em 0.6em 1em rgba(0, 0, 0, 0.65);
}
.clamp-l::before {
  left: -0.9em;
}
.clamp-r::before {
  right: -0.9em;
}

.clamp-r .tube {
  background: linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.55) 0%,
      rgba(255, 255, 255, 0) 22%
    ),
    linear-gradient(
      270deg,
      rgba(0, 0, 0, 0.6) 0%,
      rgba(0, 0, 0, 0.2) 8%,
      rgba(0, 0, 0, 0) 20%,
      rgba(0, 0, 0, 0) 78%,
      rgba(0, 0, 0, 0.3) 90%,
      rgba(0, 0, 0, 0.55) 100%
    ),
    linear-gradient(
      165deg,
      #180702 0%,
      #3d190a 10%,
      #8a4218 24%,
      #d1783a 38%,
      #ffdcb8 48%,
      #f4b47a 56%,
      #c1692c 68%,
      #6e3416 82%,
      #180702 100%
    );
}

.label {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-weight: 700;
  font-size: 3em;
  letter-spacing: 0.8em;
  color: #0d352b;
  text-shadow:
    0 0.1em 0 rgba(220, 255, 235, 0.4),
    0 0 1em rgba(53, 240, 150, 0.35);
  padding-left: 0.8em;
  transition: text-shadow 0.4s ease;
}

.hw:active {
  transform: rotateX(30deg) rotateZ(-7deg) translateY(0.25em);
  transition: transform 0.1s cubic-bezier(0.55, 0, 0.7, 0.4);
  animation: hwPress 0.22s cubic-bezier(0.4, 0, 0.6, 1);
}
.hw:active .plate {
  transform: translateY(0.3em) scale(0.975);
  transition:
    transform 0.1s cubic-bezier(0.55, 0, 0.7, 0.4),
    box-shadow 0.1s ease;
  animation: platePress 0.22s cubic-bezier(0.4, 0, 0.6, 1);
  box-shadow:
    inset 0 0.5em 0.9em rgba(8, 22, 17, 0.72),
    inset 0 -0.2em 0.4em rgba(255, 255, 255, 0.1),
    inset 0.3em 0 0.6em rgba(255, 255, 255, 0.12),
    inset -0.3em 0 0.7em rgba(10, 25, 20, 0.38),
    0 0 0 0.2em rgba(8, 18, 14, 0.92),
    0 0.6em 1.4em rgba(0, 0, 0, 0.55);
}
.hw:active .ring {
  transform: translateY(0.3em) scale(0.975);
  transition: transform 0.1s cubic-bezier(0.55, 0, 0.7, 0.4);
  animation: platePress 0.22s cubic-bezier(0.4, 0, 0.6, 1);
}
.hw:active .base {
  transition: box-shadow 0.12s ease;
  box-shadow:
    inset 0 0.1em 0 rgba(255, 255, 255, 0.08),
    0 0.35em 0 #0b0f13,
    0 0.6em 0 #180702,
    0 0.8em 0 #3d190a,
    0 1em 0 #8a4218,
    0 1.1em 0 #d1783a,
    0 1.2em 0 #ffdcb8,
    0 1.3em 0 #c1692c,
    0 1.5em 0 #6e3416,
    0 1.65em 0 #180702,
    0 1.8em 0 #0b0f13,
    0 2.1em 0 #06090c,
    0 2.8em 4.4em rgba(0, 0, 0, 0.74);
}
.hw:active .tube {
  transform: translateY(0.2em);
  transition: transform 0.12s cubic-bezier(0.55, 0, 0.7, 0.4) 0.02s;
  animation: tubePress 0.24s cubic-bezier(0.4, 0, 0.6, 1);
}
.hw:active .tube::after {
  animation: crestBlip 0.25s ease;
}
.hw:active .slot {
  transition: box-shadow 0.12s ease;
  box-shadow:
    inset 0 0.3em 0.6em #000,
    inset 0 -0.2em 0.4em #000,
    0 0.1em 0 rgba(255, 255, 255, 0.22),
    0 0 1.2em 0.3em rgba(53, 240, 150, 0.5);
}
.hw:active .label {
  transition: text-shadow 0.12s ease;
  text-shadow:
    0 0.1em 0 rgba(220, 255, 235, 0.3),
    0 0 1.4em rgba(53, 240, 150, 0.55);
}

@keyframes hwPress {
  0% {
    transform: rotateX(28deg) rotateZ(-7deg) translateY(0);
  }
  45% {
    transform: rotateX(31deg) rotateZ(-7deg) translateY(0.35em);
  }
  68% {
    transform: rotateX(29.3deg) rotateZ(-7deg) translateY(0.2em);
  }
  100% {
    transform: rotateX(30deg) rotateZ(-7deg) translateY(0.25em);
  }
}
@keyframes platePress {
  0% {
    transform: translateY(0) scale(1);
  }
  45% {
    transform: translateY(0.4em) scale(0.97);
  }
  68% {
    transform: translateY(0.26em) scale(0.973);
  }
  100% {
    transform: translateY(0.3em) scale(0.975);
  }
}
@keyframes tubePress {
  0% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(0.28em);
  }
  75% {
    transform: translateY(0.16em);
  }
  100% {
    transform: translateY(0.2em);
  }
}
@keyframes crestBlip {
  0% {
    opacity: 0.95;
  }
  45% {
    opacity: 1;
  }
  100% {
    opacity: 0.95;
  }
}

@media (prefers-reduced-motion: reduce) {
  .engage,
  .engage * {
    animation: none !important;
    transition: none !important;
  }
}
